import{_ as e,o as t,c as p,a3 as s}from"./chunks/framework.DdpBa4_E.js";const _="/ReadBooks/assets/image-092.DcTOOJTq.jpg",o="/ReadBooks/assets/image-056.Fya9PhYD.jpg",h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/87-东急田园都市线沿线的“上流化”.md","filePath":"books/xialiu-shehui/87-东急田园都市线沿线的“上流化”.md","lastUpdated":1794732511000}'),i={name:"books/xialiu-shehui/87-东急田园都市线沿线的“上流化”.md"};function r(l,a,n,d,c,u){return t(),p("div",null,[...a[0]||(a[0]=[s('<h2 id="东急田园都市线沿线的-上流化" tabindex="-1">东急田园都市线沿线的“上流化” <a class="header-anchor" href="#东急田园都市线沿线的-上流化" aria-label="Permalink to &quot;东急田园都市线沿线的“上流化”&quot;">​</a></h2><p>就这样，人们大批迁居到郊外，他们将自己视为中流阶层的一员。特别是第二次生育高峰以后出生的世代，一生下来就在郊外中流阶层的环境中长大成人。但是，如果从阶层化的观点来看，那么在哪个郊外出生并长大或许就将决定他究竟是不是真的属于某个阶层。</p><p>根据前述的“欲求调查”，让我们来看看居住在不同地区的团块次代的阶层意识（见表8-1）。由于调查选取的样本数量较少，所以只能当作参考。</p><p>表8-1　居住在不同地区的团块次代的阶层意识</p><p><img src="'+_+'" alt="" loading="lazy"></p><p>资料出处：Culture Studies研究所、e-FALCON共同实施的“欲求调查”</p><p>男性中，居住在横滨市、川崎市及埼玉县的人群里属于上流阶层的比例较高。女性的“上流”比例与男性相比虽没有显著的差别，但其中流阶层所占比例高达七成，而下流阶层的比例则非常低，这就意味着住在横滨、川崎的人阶层意识相对较高。因此，居住横滨、川崎的人整体上阶层意识较高，也成了男性和女性共同的特征之一。</p><p>再根据“第一次女性阶层化调查”来进一步观察33—37岁这个年龄层，可以清楚发现以下倾向（见表8-2）：</p><p>表8-2　居住在不同地区33—37岁女性的阶层意识</p><p><img src="'+o+'" alt="" loading="lazy"></p><p>资料出处：Culture Studies研究所、读卖广告社共同实施的“第一次女性阶层化调查”</p><p>在东京都23区的居住者中，居住在东部的该年龄层女性属于上流阶层的占22%，尽管只比东京23区西部的上流阶层比例略微高出一点，但呈现出人数逐渐增多的趋势。</p><p>不过，虽然居住在西部的下流阶层人数仅有33.0%，但在东部却多达43.9%。可以说东部已经出现了“上流”和“下流”两极分化的现象。其中的原因在于东京23区东部向来就是蓝领阶层聚居的地方，而近年来搬入该区域高层住宅的上流阶层人数也在逐渐增加。</p><p>与东京都23区西部一样，居住在横滨市、川崎市的下流阶层人数也不多，占33%~35%。虽说上流阶层只占8%，但人数最多的中流阶层所占比例竟高达57.3%。“上流”和“下流”少，“中流”居多，这种倾向与三多摩地区的情形是相同的。</p><p>令人稍感意外的是，埼玉县的居住者中上流阶层的比例较想象中的要高，占到了11.2%。不过从笔者以往的调查经验来看，埼玉县居住者的阶层意识近年来确有上升的趋势，如此也就不足为奇了。因为埼玉县范围很广，像住在浦和市、大宫市一带的人，其阶层意识与东京23区不相上下，也是“上流”者居多。</p>',15)])])}const f=e(i,[["render",r]]);export{h as __pageData,f as default};
